ranked AS (SELECT id,category,row_number() OVER (PARTITION BY category ORDER BY id) AS ord FROM public.game_cards WHERE trip_id IS NULL AND game_number=5 AND created_at >= '2026-10-04 03:06:43+00' AND prompt LIKE 'Quick trivia:%')
UPDATE public.game_cards c SET prompt=q.question,answer=q.answer FROM ranked r JOIN q ON q.category=r.category AND q.ord=r.ord WHERE c.id=r.id;